"use strict";

const { createRequire } = require("node:module");

// The Android node build runs with --expose-internals. That flag makes internal
// builtins visible through a normal createRequire call, so no N-API addon is
// needed on this platform.
const requireFromHere = createRequire(__filename);

function requireBuiltin(moduleId) {
  return requireFromHere(moduleId);
}

function isAllowedInternalId() {
  return true;
}

function getBindingInfo() {
  return {
    variant: "expose-internals",
    platform: process.platform,
    arch: process.arch,
  };
}

module.exports = {
  requireBuiltin,
  isAllowedInternalId,
  getBindingInfo,
  default: { requireBuiltin, isAllowedInternalId, getBindingInfo },
};
